css.editor.css:
/* Štýly pre editor blokov – tmavý vzhľad ako na webe. */
body.editor-styles-wrapper{background:#131313;color:#F5F5F2;font-family:'Inter',system-ui,sans-serif;font-size:19px;line-height:1.7}
.editor-styles-wrapper h1,.editor-styles-wrapper h2,.editor-styles-wrapper h3,.editor-styles-wrapper .editor-post-title__input{font-family:'Bricolage Grotesque','Inter',sans-serif;font-weight:800;color:#fff;letter-spacing:-.02em}
.editor-styles-wrapper a{color:#3CFFD0}
.editor-styles-wrapper blockquote{border-left:4px solid #3CFFD0;padding-left:22px;font-family:'Bricolage Grotesque','Inter',sans-serif;font-size:28px;font-weight:800}

.editor-styles-wrapper ul,.editor-styles-wrapper ol{padding-left:1.4em}
.editor-styles-wrapper li::marker{color:#3CFFD0;font-weight:800}
.editor-styles-wrapper ul.is-style-rl-check{list-style:"✓  "}
.editor-styles-wrapper ul.is-style-rl-cross{list-style:"✗  "}

css.relife.css:
/* RELIFE – hlavné štýly. Tmavý režim je predvolený. */
/* Náhradné písma s rovnakými rozmermi ako Inter a Bricolage Grotesque: po načítaní webfontu sa text nepreskupí (nižší CLS). */
@font-face{font-family:'Inter Fallback';src:local('Arial'),local('Helvetica'),local('Liberation Sans');font-weight:400 500;size-adjust:106.8%;ascent-override:90.7%;descent-override:22.6%;line-gap-override:0%}
@font-face{font-family:'Inter Fallback';src:local('Arial Bold'),local('Helvetica Bold'),local('Liberation Sans Bold');font-weight:600 700;size-adjust:102.4%;ascent-override:94.6%;descent-override:23.6%;line-gap-override:0%}
@font-face{font-family:'Bricolage Fallback';src:local('Arial'),local('Helvetica'),local('Liberation Sans');font-weight:400 600;size-adjust:103.1%;ascent-override:90.2%;descent-override:26.2%;line-gap-override:0%}
@font-face{font-family:'Bricolage Fallback';src:local('Arial Bold'),local('Helvetica Bold'),local('Liberation Sans Bold');font-weight:700 900;size-adjust:99.7%;ascent-override:93.3%;descent-override:27.1%;line-gap-override:0%}

:root{
	--rl-bg:#131313;--rl-surface:#1F1F1F;--rl-black:#000;--rl-ink:#F5F5F2;--rl-muted:#A6A6A6;--rl-soft:#C9C9CF;
	--rl-line:#3D3D3D;--rl-accent:#3CFFD0;--rl-ultraviolet:#5200FF;--rl-dark:#131313;
	--rl-display:'Bricolage Grotesque','Bricolage Fallback','Inter Fallback',system-ui,sans-serif;
	--rl-body:'Inter','Inter Fallback',system-ui,-apple-system,'Segoe UI',sans-serif;
	--rl-radius:22px;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--rl-bg);color:var(--rl-ink);font-family:var(--rl-body);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
a:hover .rl-card__title,a.rl-link:hover{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:4px}
button{font:inherit;color:inherit}
:focus-visible{outline:3px solid var(--rl-accent);outline-offset:2px}
.screen-reader-text{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.screen-reader-text:focus{left:8px;top:8px;width:auto;height:auto;background:#fff;color:#000;padding:10px 16px;z-index:100000}
[hidden]{display:none !important}

.rl-wrap{max-width:1280px;margin:0 auto;padding:0 32px}
.rl-block{padding-top:44px;padding-bottom:20px}
.rl-muted{color:var(--rl-muted)}
.rl-accent{color:var(--rl-accent)}
.rl-lead{font-size:18px;max-width:680px;margin:0 0 24px}
.rl-center{text-align:center}
.rl-kicker{font-size:11px;letter-spacing:.12em;font-weight:700;color:var(--rl-accent)}
.rl-kicker--ink{color:inherit}
.rl-pagetitle{font-family:var(--rl-display);font-weight:800;font-size:clamp(40px,7vw,72px);line-height:1;letter-spacing:-.03em;margin:8px 0 14px}
.rl-link{font-size:14px;font-weight:600;white-space:nowrap}

/* Hlavička */
.rl-header{background:var(--rl-bg);border-bottom:1px solid var(--rl-line)}
.rl-header__row{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding-top:14px;padding-bottom:14px}
.rl-brand{display:block;min-width:0}
/* Nahrané logo: kontajner aj obrázok majú pevný strop, takže logo nikdy nezaberie celú šírku hlavičky. */
.rl-brand--logo{flex:0 0 auto;width:auto;max-width:min(340px,55vw);overflow:hidden}
.rl-brand .custom-logo-link{display:block;line-height:0;max-width:100%}
.rl-brand .custom-logo{display:block !important;width:auto !important;height:min(var(--rl-logo-h,72px),var(--rl-logo-nat-h,9999px)) !important;max-width:100% !important;max-height:none !important;aspect-ratio:var(--rl-logo-ratio,auto) !important;object-fit:contain}
.rl-brand__mark{display:block;font-family:var(--rl-display);font-weight:800;font-size:60px;letter-spacing:-.04em;line-height:.9}
.rl-brand__tag{display:block;margin-top:6px;font-size:11px;font-weight:700;letter-spacing:.14em;color:var(--rl-accent)}
.rl-nav__list{display:flex;gap:2px;flex-wrap:wrap;list-style:none;margin:0;padding:0}
.rl-nav__list a{display:flex;align-items:center;min-height:44px;padding:0 14px;border-radius:999px;font-weight:600;font-size:16px}
.rl-nav__list a:hover,.rl-nav__list .current-menu-item>a{background:#2E2E2E}
.rl-header__tools{display:flex;align-items:center;gap:10px}
.rl-iconbtn{width:44px;height:44px;border:none;background:transparent;display:flex;align-items:center;justify-content:center;cursor:pointer}
.rl-search{border-top:1px solid var(--rl-line);padding:14px 0;background:var(--rl-surface)}
.rl-searchform{display:flex;gap:10px}
.rl-searchform input{flex:1;min-height:48px;border-radius:999px;border:1.5px solid var(--rl-line);background:var(--rl-bg);color:var(--rl-ink);padding:0 20px;font:inherit}
.rl-searchform button{min-height:48px;padding:0 24px;border-radius:999px;border:none;background:var(--rl-accent);color:#131313;font-weight:700;cursor:pointer}
.rl-searchbox{margin:0 0 28px;max-width:640px}

/* Pilulky a štítky */
.rl-pill{display:inline-flex;align-items:center;gap:8px;min-height:48px;padding:0 22px;border-radius:999px;font-weight:700;font-size:15px;border:1.5px solid transparent;cursor:pointer}
.rl-pill--accent{background:var(--rl-accent);color:#131313}
.rl-pill--dark{background:#131313;color:#fff}
.rl-pill--outline{border-color:#fff;background:transparent;color:#fff}
.rl-count{min-width:22px;height:22px;border-radius:11px;background:var(--rl-accent);color:#131313;font-size:12px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;padding:0 6px}
.rl-tag{display:inline-block;background:var(--rl-accent);color:#131313;font-weight:700;font-size:11px;letter-spacing:.1em;padding:4px 10px;border-radius:8px}
.rl-tag--dark{background:#131313;color:#fff}
.rl-tag--accent{background:var(--rl-accent);color:#131313}
.rl-badge{display:inline-block;background:var(--rl-accent);color:#131313;font-weight:700;font-size:13px;letter-spacing:.04em;padding:9px 16px;border-radius:12px}
.rl-badge--accent{font-size:12px;letter-spacing:.1em;padding:5px 12px;border-radius:8px}
.rl-meta{display:block;font-size:12px;color:var(--rl-muted)}

/* Hero */
.rl-hero{background:var(--rl-bg);padding:20px 0}
.rl-hero__grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:20px}
.rl-herocard{position:relative;display:block;min-height:560px;border-radius:var(--rl-radius);overflow:hidden;color:#fff}
.rl-herocard__bg{position:absolute;inset:0}
.rl-herocard__bg img{width:100%;height:100%;object-fit:cover}
.rl-herocard__big{position:absolute;right:24px;top:-40px;font-family:var(--rl-display);font-weight:800;font-size:420px;line-height:1;opacity:.1}
.rl-herocard .rl-badge{position:absolute;left:20px;top:20px}
.rl-herocard__body{position:absolute;left:0;right:0;bottom:0;padding:32px 36px;background:rgba(19,19,19,.62);display:block}
.rl-herocard__title{font-family:var(--rl-display);font-weight:800;font-size:clamp(28px,3.4vw,46px);line-height:1.05;letter-spacing:-.025em;margin:0 0 12px;max-width:720px}
.rl-herocard__meta{display:block;font-size:15px;font-weight:600;margin-bottom:6px}
.rl-herocard__dek{display:block;max-width:620px;color:#E6E6E6}
.rl-herocard:hover .rl-herocard__title{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:5px}

/* Anketa a nálada */
.rl-sidecard{display:flex;flex-direction:column;background:var(--rl-surface);border:1px solid var(--rl-line);border-radius:var(--rl-radius);padding:22px;min-height:560px}
.rl-tabs{display:flex;gap:6px;background:var(--rl-bg);border-radius:999px;padding:4px;margin-bottom:18px}
.rl-tabs__btn{flex:1;min-height:44px;border:none;border-radius:999px;background:transparent;font-weight:700;font-size:14px;cursor:pointer}
.rl-tabs__btn.is-active{background:var(--rl-accent);color:#131313}
.rl-panel{display:flex;flex-direction:column;flex:1}
.rl-poll{display:flex;flex-direction:column;flex:1}
.rl-poll__head{display:flex;align-items:center;gap:12px;color:var(--rl-accent)}
.rl-poll__kicker{font-family:var(--rl-display);font-weight:800;font-size:20px;color:var(--rl-accent);line-height:1.1}
.rl-poll__q{font-family:var(--rl-display);font-weight:800;font-size:26px;line-height:1.1;margin:16px 0 10px;letter-spacing:-.01em}
.rl-poll__opts{flex:1}
.rl-opt{display:block;width:100%;text-align:left;background:transparent;border:none;padding:9px 0;cursor:pointer;color:#fff}
.rl-opt__row{display:flex;align-items:center;gap:12px;min-height:28px}
.rl-opt__radio{flex:0 0 22px;height:22px;border-radius:50%;border:2px solid #6B6B6B;display:flex;align-items:center;justify-content:center}
.rl-opt__radio i{width:10px;height:10px;border-radius:50%;background:transparent}
.rl-opt__label{flex:1;font-size:16px}
.rl-opt__pct{font-size:14px;font-weight:600;color:var(--rl-soft)}
.rl-opt__bar{display:block;margin:6px 0 0 34px;height:8px;border-radius:8px;background:var(--rl-line);overflow:hidden}
.rl-opt__bar span{display:block;height:8px;width:0;border-radius:8px;background:#8A8A8A;transition:width .5s ease}
.rl-opt.is-mine .rl-opt__radio{border-color:var(--rl-accent)}
.rl-opt.is-mine .rl-opt__radio i{background:var(--rl-accent)}
.rl-opt.is-mine .rl-opt__label{font-weight:700}
.rl-opt.is-mine .rl-opt__bar span{background:var(--rl-accent)}
.rl-poll.is-voted .rl-opt{cursor:default}
.rl-poll__note{margin:14px 0 0;font-size:13px;color:var(--rl-soft)}
.rl-outline-link{display:flex;align-items:center;justify-content:space-between;margin-top:14px;min-height:48px;padding:0 16px;border-radius:12px;border:1.5px solid var(--rl-ink);font-weight:600;font-size:15px}
.rl-moods{display:flex;flex-direction:column;gap:8px;flex:1;margin-top:6px}
.rl-mood{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;min-height:52px;padding:0 16px;border-radius:14px;border:1.5px solid var(--rl-line);background:transparent;font-weight:600;font-size:16px;text-align:left;cursor:pointer}
.rl-mood__hint{font-size:11px;letter-spacing:.08em;font-weight:700;opacity:.8}
.rl-mood[aria-pressed="true"]{background:var(--rl-accent);border-color:var(--rl-accent);color:#131313}

/* Sekcie bloku */
.rl-sechead{display:flex;justify-content:space-between;align-items:baseline;gap:16px;flex-wrap:wrap;margin-bottom:18px}
.rl-sechead__title{font-family:var(--rl-display);font-weight:800;font-size:clamp(26px,3vw,36px);letter-spacing:-.02em;line-height:1.05;margin:0 0 18px}
.rl-sechead .rl-sechead__title{margin:0}
.rl-sechead__note{margin:0;max-width:420px}
.rl-moodstatus{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:-4px 0 16px;padding:10px 14px;border-radius:12px;background:var(--rl-surface);font-size:14px}
.rl-moodstatus .rl-pill{min-height:44px;font-size:13px;padding:0 14px}

/* Mriežky */
.rl-grid{display:grid;gap:20px}
.rl-grid--4{grid-template-columns:repeat(4,minmax(0,1fr))}
.rl-grid--3{grid-template-columns:repeat(3,minmax(0,1fr));gap:36px}
.rl-grid--2{grid-template-columns:repeat(2,minmax(0,1fr))}

/* Karta článku */
.rl-card{position:relative}
.rl-card__link{display:block}
.rl-card__media{display:block;position:relative;aspect-ratio:1/1.05;border-radius:16px;overflow:hidden}
.rl-card__media img{width:100%;height:100%;object-fit:cover}
.rl-card__initial{position:absolute;left:10px;bottom:-26px;font-family:var(--rl-display);font-weight:800;font-size:140px;line-height:1;color:#131313;opacity:.12}
.rl-card__media .rl-tag{position:absolute;left:10px;top:10px}
.rl-card__title{font-family:var(--rl-display);font-weight:800;font-size:19px;line-height:1.15;margin:12px 0 6px}
.rl-card.is-hidden{display:none}
.rl-save{position:absolute;right:8px;top:8px;width:44px;height:44px;border-radius:50%;border:none;background:rgba(19,19,19,.82);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer}
.rl-save[aria-pressed="true"]{background:var(--rl-accent);color:#131313}
.rl-save[aria-pressed="true"] svg{fill:currentColor}
.rl-save--inline{position:static;border:1.5px solid var(--rl-ink);background:transparent;color:var(--rl-ink)}

/* Quick take */
.rl-quick{display:block;background:var(--rl-surface);border:1px solid var(--rl-line);border-radius:18px;padding:18px}
.rl-quick__title{display:block;margin:10px 0 8px;font-family:var(--rl-display);font-size:18px;line-height:1.2;font-weight:500}
.rl-quick:hover{border-color:var(--rl-accent)}

/* Široké karty */
.rl-wide{display:flex;min-height:150px;border-radius:18px;overflow:hidden;background:var(--rl-surface)}
.rl-wide__media{flex:0 0 38%;display:block}
.rl-wide__media img{width:100%;height:100%;object-fit:cover}
.rl-wide__body{flex:1;padding:18px;display:flex;flex-direction:column;justify-content:center;gap:8px;min-width:0}
.rl-wide__body .rl-tag{align-self:flex-start}
.rl-wide__title{font-family:var(--rl-display);font-weight:800;font-size:22px;line-height:1.1}

/* Piliere */
.rl-pillar__bar{height:8px;border-radius:999px}
.rl-pillar__head h3{font-family:var(--rl-display);font-weight:800;font-size:30px;letter-spacing:-.02em;margin:14px 0 4px}
.rl-pillar .rl-card{margin:14px 0}
.rl-list{border-top:1.5px solid var(--rl-ink);margin-top:14px}
.rl-list__item{display:block;padding:12px 0;border-bottom:1px solid var(--rl-line)}
.rl-list__format{display:block;font-size:11px;font-weight:700;letter-spacing:.1em;color:var(--rl-muted)}
.rl-list__title{display:block;margin-top:3px;font-family:var(--rl-display);font-size:17px;line-height:1.2;font-weight:500}
.rl-list__item:hover .rl-list__title{text-decoration:underline}

/* Versus */
.rl-versus{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr);gap:40px;align-items:center;background:var(--rl-surface);border-radius:26px;padding:40px}
.rl-versus__title{font-family:var(--rl-display);font-weight:800;font-size:clamp(28px,3.4vw,42px);line-height:1;letter-spacing:-.025em;margin:18px 0 12px}
.rl-versus__cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.rl-vs{border-radius:18px;padding:22px;color:#131313}
.rl-vs--a{background:#3CFFD0}.rl-vs--b{background:#FFE14D}
.rl-vs h3{font-family:var(--rl-display);font-weight:800;font-size:28px;margin:0 0 12px}
.rl-vs dl{margin:0}
.rl-vs dt{font-size:11px;letter-spacing:.1em;font-weight:700;border-top:1.5px solid #131313;padding-top:10px}
.rl-vs dd{margin:2px 0 10px;font-size:16px;font-weight:500}

/* Dlaždice sekcií */
.rl-tiles{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px}
.rl-tile{position:relative;display:flex;flex-direction:column;justify-content:flex-end;min-height:190px;border-radius:18px;padding:14px;overflow:hidden;color:#131313}
.rl-tile__initial{position:absolute;left:8px;top:-14px;font-family:var(--rl-display);font-weight:800;font-size:110px;line-height:1;opacity:.14}
.rl-tile__name{position:relative;font-family:var(--rl-display);font-weight:800;font-size:19px}
.rl-tile__line{position:relative;margin-top:4px;font-size:12px;line-height:1.3;font-weight:500}
.rl-tile:hover{transform:translateY(-3px)}

/* Pásy */
.rl-band{padding:48px 0;margin-top:28px}
.rl-band--surface{background:var(--rl-surface)}
.rl-band--black{background:var(--rl-black);color:#fff}
.rl-col__head{display:flex;align-items:center;gap:10px;padding-bottom:12px;border-bottom:1.5px solid var(--rl-ink)}
.rl-col__head h3{font-family:var(--rl-display);font-weight:800;font-size:24px;margin:0}
.rl-dot{width:14px;height:14px;border-radius:50%;display:inline-block}
.rl-format{display:block;background:var(--rl-surface);border:1px solid var(--rl-line);border-radius:18px;padding:22px;min-height:180px}
.rl-format__top{display:flex;justify-content:space-between;align-items:center}
.rl-format__no{font-family:var(--rl-display);font-size:26px;font-weight:800;color:#6B6B6B}
.rl-format h3{font-family:var(--rl-display);font-size:22px;line-height:1.15;font-weight:800;margin:20px 0 6px}
.rl-format p{margin:0;font-size:14px;line-height:1.5;color:var(--rl-soft)}
.rl-format:hover{border-color:var(--rl-accent)}
.rl-formats{gap:16px}
.rl-guide{display:flex;flex-direction:column;justify-content:space-between;min-height:240px;border-radius:20px;padding:22px;color:#131313}
.rl-guide__title{display:block;font-family:var(--rl-display);font-weight:800;font-size:26px;line-height:1.05;margin-bottom:8px}
.rl-guide__meta{font-size:12px;font-weight:700}
.rl-guide .rl-tag{align-self:flex-start}

/* Archív */
.rl-archivehead{padding:44px 0 8px}
.rl-archivehead__bar{display:block;width:96px;height:10px;border-radius:999px;background:var(--rl-section,var(--rl-accent));margin-bottom:12px}

/* Článok */
.rl-progress{height:4px;background:var(--rl-line);position:sticky;top:0;z-index:50}
.rl-progress span{display:block;height:4px;width:0;background:var(--rl-accent)}
.rl-article__head{padding-top:36px;padding-bottom:28px}
.rl-crumbs{display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:13px;color:var(--rl-muted)}
.rl-crumbs a{min-height:32px;display:inline-flex;align-items:center}
.rl-article__tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}
.rl-article__title{font-family:var(--rl-display);font-weight:800;font-size:clamp(34px,5.2vw,68px);line-height:1;letter-spacing:-.03em;margin:18px 0;max-width:1000px}
.rl-article__dek{font-size:22px;line-height:1.45;color:#D8D8DC;max-width:820px;margin:0 0 26px}
.rl-byline{display:flex;align-items:center;gap:14px;flex-wrap:wrap;font-size:14px}
.rl-byline__name{font-weight:600}
.rl-byline__actions{margin-left:auto;display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.rl-avatar{border-radius:50%}
.rl-article__hero{margin:32px auto 40px}
.rl-article__hero img{width:100%;aspect-ratio:21/9;object-fit:cover;border-radius:20px}
.rl-article__hero figcaption{margin-top:10px;font-size:13px}
.rl-article__cols{display:flex;gap:56px;align-items:flex-start;flex-wrap:wrap;padding-bottom:64px}
.rl-toc{flex:0 0 220px;position:sticky;top:20px;font-size:14px}
.rl-toc ol{list-style:none;margin:8px 0 0;padding:0;border-top:1.5px solid var(--rl-ink)}
.rl-toc li a{display:block;padding:10px 0;border-bottom:1px solid var(--rl-line);color:var(--rl-muted);line-height:1.35}
.rl-toc li a:hover{color:#fff}
.rl-article__main{flex:1 1 640px;min-width:0;max-width:760px}
.rl-answer{background:var(--rl-surface);border:1.5px solid var(--rl-accent);border-radius:20px;padding:26px;margin-bottom:36px}
.rl-answer p{font-family:var(--rl-display);font-size:24px;line-height:1.3;font-weight:500;margin:10px 0 0;color:#fff}
.rl-content{font-size:19px;line-height:1.7;color:#E6E6E6}
.rl-content h2{font-family:var(--rl-display);font-size:34px;line-height:1.1;font-weight:800;letter-spacing:-.02em;margin:48px 0 16px;color:#fff;scroll-margin-top:24px}
.rl-content h3{font-family:var(--rl-display);font-size:24px;font-weight:800;margin:32px 0 10px;color:#fff}
:root .rl-content a{color:var(--rl-accent);text-decoration:underline;text-underline-offset:3px}
.rl-content blockquote{margin:32px 0;padding:0 0 0 22px;border-left:4px solid var(--rl-accent);font-family:var(--rl-display);font-size:28px;line-height:1.2;font-weight:800;color:#fff}
.rl-content figure{margin:32px 0}
.rl-content img{border-radius:16px}
.rl-sources{border-top:1.5px solid var(--rl-ink);padding-top:20px;margin-top:36px;font-size:14px;color:var(--rl-muted)}
.rl-sources ol{margin:8px 0;padding-left:20px}
.rl-disclosure{padding:14px 16px;border:1px dashed var(--rl-line);border-radius:12px;margin:14px 0 0}
.rl-author{display:flex;gap:16px;align-items:center;background:var(--rl-surface);border-radius:16px;padding:20px;margin-top:30px}

/* Ankety a výsledky */
.rl-activepoll{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;background:var(--rl-accent);color:#131313;border-radius:20px;padding:20px 24px;margin:0 0 24px}
.rl-activepoll__q{display:block;font-family:var(--rl-display);font-weight:800;font-size:24px;margin-top:4px}
.rl-filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}
.rl-filter{min-height:44px;padding:0 18px;border-radius:999px;border:1.5px solid var(--rl-line);background:transparent;font-weight:600;font-size:14px;cursor:pointer}
.rl-filter.is-active{background:var(--rl-accent);border-color:var(--rl-accent);color:#131313}
.rl-pollcard{background:var(--rl-surface);border:1px solid var(--rl-line);border-radius:var(--rl-radius);padding:24px}
.rl-pollcard.is-hidden{display:none}
.rl-pollcard__top{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center;font-size:12px}
.rl-pollcard h2{font-family:var(--rl-display);font-weight:800;font-size:24px;line-height:1.12;margin:14px 0 8px}
.rl-result{padding:9px 0;color:var(--rl-soft)}
.rl-result__row{display:flex;justify-content:space-between;gap:12px;font-size:15px}
.rl-result__bar{margin-top:6px;height:8px;border-radius:8px;background:var(--rl-line);overflow:hidden}
.rl-result__bar span{display:block;height:8px;border-radius:8px;background:#8A8A8A}
.rl-result.is-win{color:#fff;font-weight:700}
.rl-result.is-win .rl-result__bar span{background:var(--rl-accent)}

/* Newsletter a pätička */
.rl-footer{background:var(--rl-black);color:#fff;margin-top:56px;padding:48px 0 32px}
.rl-footer__grid{display:grid;grid-template-columns:1.2fr 1.4fr 1fr;gap:48px}
.rl-footer__mark{font-family:var(--rl-display);font-weight:800;font-size:56px;letter-spacing:-.04em;line-height:.9}
.rl-footer__text{color:var(--rl-soft);font-size:14px;max-width:340px}
.rl-newsletter{background:var(--rl-ultraviolet);border-radius:22px;padding:24px}
.rl-newsletter__title{font-family:var(--rl-display);font-weight:800;font-size:28px;margin:0 0 6px}
.rl-newsletter p{margin:0 0 14px;font-size:14px}
.rl-newsletter__form{display:flex;gap:10px;flex-wrap:wrap}
.rl-newsletter__form input[type="email"]{flex:1 1 200px;min-height:48px;padding:0 16px;border-radius:12px;border:2px solid transparent;font:inherit;font-size:16px;background:#fff !important;color:#131313 !important;-webkit-text-fill-color:#131313;caret-color:#131313;box-shadow:none}
.rl-newsletter__form input[type="email"]::placeholder{color:#5A5A62;opacity:1;-webkit-text-fill-color:#5A5A62}
.rl-newsletter__form input[type="email"]:focus{outline:none;border-color:var(--rl-accent);box-shadow:0 0 0 3px rgba(60,255,208,.35)}
.rl-newsletter__form input[type="email"]:-webkit-autofill,.rl-newsletter__form input[type="email"]:-webkit-autofill:focus{-webkit-text-fill-color:#131313;box-shadow:0 0 0 100px #fff inset}
.rl-newsletter__form button{min-height:48px;padding:0 24px;border-radius:12px;border:1.5px solid #fff;background:#131313;color:#fff;font-weight:700;cursor:pointer}
.rl-footer__list{list-style:none;margin:0;padding:0}
.rl-footer__list a{display:flex;align-items:center;min-height:36px;color:#E6E6EA}
.rl-footer__legal{margin-top:36px;padding-top:18px;border-top:1px solid var(--rl-line);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13px;color:var(--rl-muted)}

/* Spodné menu na mobile */
.rl-tabbar{display:none}

@media (max-width:1100px){
	.rl-hero__grid,.rl-versus{grid-template-columns:minmax(0,1fr)}
