	.rl-grid--3,.rl-grid--2,.rl-versus__cards{grid-template-columns:minmax(0,1fr)}
	.rl-grid--4{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
	.rl-scroll-m{display:flex;overflow-x:auto;scrollbar-width:none;margin:0 -16px;padding:0 16px 4px}
	.rl-scroll-m>*{flex:0 0 260px}
