/* Administrácia: spustenie kontroly GDPR lišty AdSense (v skrytom rámci s úvodnou stránkou ako návštevník). */
(function () {
	'use strict';
	var cfg = window.relifeCmp || {};
	var $ = function (id) { return document.getElementById(id); };
	var icon = { ok: '✅', warn: '⚠️', fail: '❌', info: 'ℹ️' };
	var ORDER = ['srv_theme', 'script', 'srv_raw', 'srv_id', 'pub', 'agload', 'fcnet', 'srv_csp', 'srv_fc', 'conflict', 'srv_plugins', 'cookie', 'region', 'fcreq', 'dom', 'tcf'];

	if (cfg.pub && !$('rl-cmp-pub').value) { $('rl-cmp-pub').value = 'ca-pub-' + cfg.pub; }

	function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }

	function clearConsent() {
		var names = ['FCCDCF', 'FCNEC', 'euconsent-v2', 'addtl_consent'];
		var host = location.hostname.split('.');
		var domains = ['', location.hostname, '.' + location.hostname];
		if (host.length > 2) { domains.push('.' + host.slice(-2).join('.')); }
		names.forEach(function (n) {
			domains.forEach(function (d) {
				document.cookie = n + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/' + (d ? '; domain=' + d : '');
			});
		});
		try { localStorage.removeItem('relife.consent'); } catch (e) { /* nič */ }
	}

	function verdict(res) {
		var byId = {};
		res.forEach(function (r) { byId[r.id] = r; });
		var i, r;
		for (i = 0; i < ORDER.length; i++) {
			r = byId[ORDER[i]];
			if (r && r.status === 'fail') { return { found: true, r: r }; }
		}
		for (i = 0; i < ORDER.length; i++) {
			r = byId[ORDER[i]];
			if (r && r.status === 'warn' && ['conflict', 'cookie', 'region', 'srv_plugins'].indexOf(r.id) > -1) { return { found: true, r: r }; }
		}
		return { found: false };
	}

	function render(res, frameOk) {
		var tb = $('rl-cmp-table').querySelector('tbody');
		tb.innerHTML = '';
		res.sort(function (a, b) {
			var w = { fail: 0, warn: 1, info: 2, ok: 3 };
			return (w[a.status] - w[b.status]);
		});
		res.forEach(function (x) {
			var tr = document.createElement('tr');
			tr.innerHTML = '<td>' + (icon[x.status] || '•') + '</td><td><strong>' + esc(x.title) + '</strong></td><td>' +
				(x.detail ? '<div>' + esc(x.detail) + '</div>' : '') +
				(x.fix && x.status !== 'ok' ? '<div style="color:#1d2327;margin-top:4px"><strong>→ ' + esc(x.fix) + '</strong></div>' : '') + '</td>';
			tb.appendChild(tr);
		});
		$('rl-cmp-table').hidden = false;
		var v = verdict(res);
		var box = $('rl-cmp-verdict');
		box.hidden = false;
		if (v.found) {
			box.style.borderLeftColor = '#d63638';
			box.innerHTML = '<h2 style="margin-top:0">Najpravdepodobnejšia príčina</h2><p style="font-size:15px"><strong>' + esc(v.r.title) + '</strong></p><p>Návrh opravy: ' + esc(v.r.fix) + '</p>';
		} else {
			box.style.borderLeftColor = frameOk ? '#00a32a' : '#dba617';
			box.innerHTML = '<h2 style="margin-top:0">' + (frameOk ? 'Nenašla sa jednoznačná chyba' : 'Test sa dokončil len čiastočne') + '</h2><p>Pozrite upozornenia v tabuľke. Ak lišta stále chýba, otvorte web v novom anonymnom okne zo slovenskej siete.</p>';
		}
		$('rl-cmp-copy').hidden = false;
		$('rl-cmp-copy').onclick = function () {
			var txt = res.map(function (x) { return (icon[x.status] || '•') + ' ' + x.title + (x.detail ? '\n   ' + x.detail : '') + (x.fix && x.status !== 'ok' ? '\n   → ' + x.fix : ''); }).join('\n');
			if (navigator.clipboard) { navigator.clipboard.writeText(txt); $('rl-cmp-copy').textContent = 'Skopírované'; }
		};
	}

	function runFrame(wait) {
		return new Promise(function (resolve) {
			var fr = $('rl-cmp-frame');
			var done = false;
			var finish = function (v) { if (!done) { done = true; resolve(v); } };
			fr.onload = function () {
				setTimeout(function () {
					try {
						var w = fr.contentWindow;
						w.__RELIFE_CMP_NO_AUTORUN = true;
						var s = w.document.createElement('script');
						s.src = cfg.script;
						s.onload = function () {
							w.relifeCmpCheck({ pub: ($('rl-cmp-pub').value || '').replace(/\D/g, '') || cfg.pub }).then(function (r) { finish(r.results); }, function (e) { finish([{ id: 'frame', status: 'fail', title: 'Test v prehliadači zlyhal', detail: String(e), fix: '' }]); });
						};
						s.onerror = function () { finish([{ id: 'frame', status: 'fail', title: 'Nepodarilo sa načítať kontrolný skript', detail: cfg.script, fix: 'Skontrolujte, či je nahraná aktuálna verzia témy.' }]); };
						w.document.head.appendChild(s);
					} catch (e) {
						finish([{ id: 'frame', status: 'fail', title: 'Úvodnú stránku sa nepodarilo otvoriť na kontrolu', detail: String(e), fix: 'Web môže posielať hlavičku X-Frame-Options/CSP frame-ancestors, ktorá zakazuje zobrazenie v rámci. Použite postup z tools/README.md (konzola prehliadača).' }]);
					}
				}, wait * 1000);
			};
			fr.src = cfg.testUrl + '&t=' + Date.now();
			setTimeout(function () { finish([{ id: 'frame', status: 'fail', title: 'Úvodná stránka sa nenačítala včas', detail: '', fix: 'Skúste znova; pri pomalom hostingu zvýšte čakanie.' }]); }, (wait + 40) * 1000);
		});
	}

	$('rl-cmp-run').addEventListener('click', function () {
		var btn = this;
		btn.disabled = true;
		$('rl-cmp-status').textContent = 'Beží test… (približne 20 s)';
		$('rl-cmp-table').hidden = true;
		$('rl-cmp-verdict').hidden = true;
		if ($('rl-cmp-clear').checked) { clearConsent(); }
		var pub = ($('rl-cmp-pub').value || '').replace(/\D/g, '');
		var fd = new FormData();
		fd.append('action', 'relife_cmp');
		fd.append('nonce', cfg.nonce);
		fd.append('pub', pub);
		var server = fetch(cfg.ajax, { method: 'POST', credentials: 'same-origin', body: fd }).then(function (r) { return r.json(); }).then(function (j) { return j.success ? j.data : []; }).catch(function () { return []; });
		Promise.all([server, runFrame(12)]).then(function (all) {
			var frameOk = all[1].length > 0 && all[1][0].id !== 'frame';
			render(all[0].concat(all[1]), frameOk);
			$('rl-cmp-status').textContent = 'Hotovo.';
			btn.disabled = false;
		});
	});
})();

js.cmp-check.js:
/*
 * RELIFE – diagnostika: prečo sa nezobrazuje GDPR lišta (správa o súhlase) z Google AdSense.
 *
 * POUŽITIE (najjednoduchšie): otvorte relife.sk v NOVOM anonymnom okne, počkajte ~10 s, otvorte konzolu
 * (F12 → Console), vložte celý tento súbor a stlačte Enter. Výsledok sa vypíše do konzoly.
 * Alternatíva: node adsense-cmp-check.node.js https://relife.sk   (pozri README.md)
 *
 * Skript nič nemení ani neposiela nikam údaje; len číta stránku a robí jednu požiadavku na ads.txt
 * a na adresu Google Funding Choices.
 */
(function () {
	'use strict';

	var DEFAULT_PUB = '2577354057353027';

	async function relifeCmpCheck(opts) {
		opts = opts || {};
		var pub = String(opts.pub || DEFAULT_PUB).replace(/^ca-/, '').replace(/^pub-/, '');
		var res = [];
		var add = function (id, status, title, detail, fix) {
			res.push({ id: id, status: status, title: title, detail: detail || '', fix: fix || '' });
		};
		var entries = performance.getEntriesByType('resource');
		var has = function (re) { return entries.filter(function (e) { return re.test(e.name); }); };

		/* 1. Je skript AdSense na stránke? */
		var scripts = Array.prototype.slice.call(document.scripts).filter(function (s) { return /adsbygoogle\.js/.test(s.src); });
		var clients = {};
		scripts.forEach(function (s) { var m = /client=(ca-pub-\d+)/.exec(s.src); if (m) { clients[m[1]] = 1; } });
		Array.prototype.slice.call(document.querySelectorAll('ins.adsbygoogle[data-ad-client]')).forEach(function (n) { clients[n.getAttribute('data-ad-client')] = 1; });
		var clientList = Object.keys(clients);
		var loaderInline = /pagead2\.googlesyndication\.com\/pagead\/js\/adsbygoogle\.js/.test(document.documentElement.innerHTML);

		if (!scripts.length && !loaderInline) {
			add('script', 'fail', 'Skript AdSense (adsbygoogle.js) na stránke nie je',
				'Bez neho Google nemá čo načítať, preto sa nezobrazí ani lišta súhlasu.',
				'1) Vzhľad → Prispôsobiť → RELIFE – Reklamy: vyplňte ID vydavateľa alebo vložte celý kód AdSense do hlavičky (téma ho načíta po načítaní stránky). 2) Vyprázdnite cache (Starcache). 3) Skontrolujte, či nie ste prihlásený ako redaktor, ak je zapnuté „Neukazovať reklamy prihláseným redaktorom“. 4) Pri článku nesmie byť zapnuté „Nezobrazovať reklamy v tomto článku“.');
		} else {
			add('script', 'ok', 'Skript AdSense je na stránke', scripts.length ? scripts[0].src : '(vkladá sa dynamicky po načítaní stránky)');
		}

		/* 2. Zhoduje sa ID vydavateľa? */
		if (clientList.length) {
			if (clientList.indexOf('ca-pub-' + pub) === -1) {
				add('pub', 'fail', 'ID vydavateľa na stránke nie je ca-pub-' + pub, 'Nájdené: ' + clientList.join(', '),
					'Opravte ID v Customizeri alebo v kóde AdSense. Lištu GDPR zobrazuje len správa priradená k tomu istému účtu.');
			} else if (clientList.length > 1) {
				add('pub', 'warn', 'Na stránke je viac ID vydavateľov', clientList.join(', '), 'Ponechajte len jedno ID – rôzne kódy sa môžu rušiť.');
			} else {
				add('pub', 'ok', 'ID vydavateľa sedí', 'ca-pub-' + pub);
			}
		}

		/* 3. Načítal sa adsbygoogle.js? */
		var ag = has(/adsbygoogle\.js/);
		var agLoaded = !!(window.adsbygoogle && window.adsbygoogle.loaded === true);
		if ((scripts.length || loaderInline) && !ag.length && !agLoaded) {
			add('agload', 'fail', 'Skript AdSense sa nestiahol (zablokovaný alebo ešte nenačítaný)', 'V sieťových požiadavkách nie je žiadny záznam pre adsbygoogle.js.',
				'Počkajte ~10 s po načítaní stránky a spustite kontrolu znova. Ak sa nestiahne: vypnite blokovač reklám/ochranu súkromia v prehliadači, skontrolujte CSP hlavičku servera (musí povoliť pagead2.googlesyndication.com a fundingchoicesmessages.google.com).');
		} else if (ag.length || agLoaded) {
			add('agload', 'ok', 'Skript AdSense sa načítal', ag.length ? ag[0].name : 'window.adsbygoogle.loaded = true');
		}

		/* 4. Požiadavka na Funding Choices (tadiaľ prichádza GDPR správa) */
		var fc = has(/fundingchoicesmessages\.google\.com/);
		var probe = 'nezistené';
		try {
			await fetch('https://fundingchoicesmessages.google.com/i/pub-' + pub + '?ers=1', { mode: 'no-cors', cache: 'no-store' });
			probe = 'dostupné';
		} catch (e) {
			probe = 'zablokované / chyba siete';
		}
		if (probe !== 'dostupné') {
			add('fcnet', 'fail', 'Adresa Google Funding Choices je z tohto prehliadača nedostupná', 'fundingchoicesmessages.google.com → ' + probe,
				'Vypnite blokovač reklám / ochranu proti sledovaniu / DNS filter (AdGuard, uBlock, Pi-hole, Brave Shields) a skúste znova v čistom anonymnom okne.');
		}
		if (!fc.length) {
			add('fcreq', (scripts.length || agLoaded) ? 'fail' : 'warn', 'Stránka si nevyžiadala GDPR správu od Google',
				'AdSense skript sa pri načítaní neobrátil na fundingchoicesmessages.google.com. Skript to robí len vtedy, keď má účet publikovanú správu pre túto stránku.',
				'V AdSense: Súkromie a správy (Privacy & messaging) → Európske predpisy (GDPR) → vytvorte správu a stlačte „Publikovať“. Skontrolujte, že je v zozname „Stránky“ a že relife.sk má stav Pripravené (overená stránka). Po publikovaní počkajte 1–2 hodiny.');
		} else {
			add('fcreq', 'ok', 'Stránka si vyžiadala GDPR správu od Google', fc[0].name);
		}

		/* 5. Je správa v DOM? */
		var dialog = document.querySelector('.fc-consent-root, .fc-dialog-container, .fc-dialog-overlay');
		var present = document.querySelector('iframe[name="googlefcPresent"]');
		var inactive = document.querySelector('iframe[name="googlefcInactive"]');
		var visible = false;
		if (dialog) {
			var r = dialog.getBoundingClientRect();
			var cs = getComputedStyle(dialog);
			visible = r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none';
		}
		if (dialog && visible) {
			add('dom', 'ok', 'GDPR lišta Google je na stránke a je viditeľná');
		} else if (dialog && !visible) {
			add('dom', 'fail', 'GDPR lišta Google je v stránke, ale je skrytá', 'Prvok existuje, ale nie je vidieť (display/visibility/rozmery).',
				'Pravdepodobne ju prekrýva alebo skrýva CSS témy/pluginu (z-index, overflow, display:none). Vyskúšajte dočasne vypnúť pluginy na optimalizáciu CSS/JS (minifikácia, odkladanie skriptov).');
		} else if (inactive) {
			add('dom', 'fail', 'Google hlási „žiadna aktívna správa“ (googlefcInactive)', 'Skript Funding Choices sa načítal, ale pre túto stránku/návštevníka sa žiadna správa nemá zobraziť.',
				'Najčastejšie: správa nie je publikovaná alebo nie je priradená k relife.sk, návštevník nie je v EHP/UK, alebo už súhlas dal (cookie FCCDCF). Skontrolujte v AdSense → Súkromie a správy, či je GDPR správa „Aktívna“ a obsahuje relife.sk.');
		} else if (present) {
			add('dom', 'warn', 'Funding Choices je prítomný, ale lišta sa nezobrazila', 'Iframe googlefcPresent existuje, dialóg nie.', 'Súhlas bol pravdepodobne už zadaný (pozrite cookies), alebo správa čaká na publikovanie.');
		} else {
			add('dom', 'fail', 'V stránke nie je žiadny prvok Google Funding Choices', 'Neexistuje ani dialóg, ani iframe googlefcPresent/googlefcInactive.',
				'Pozri vyššie: skript sa buď nenačítal, alebo účet nemá publikovanú správu pre túto stránku.');
		}

		/* 6. TCF API (štandardné rozhranie lišty) */
		if (typeof window.__tcfapi === 'function') {
			var tc = await new Promise(function (resolve) {
				var done = false;
				var t = setTimeout(function () { if (!done) { done = true; resolve(null); } }, 3000);
				try {
					window.__tcfapi('getTCData', 2, function (d, ok) { if (!done) { done = true; clearTimeout(t); resolve(ok ? d : { error: true }); } });
				} catch (e) { if (!done) { done = true; clearTimeout(t); resolve(null); } }
			});
			if (!tc) {
				add('tcf', 'warn', 'Rozhranie TCF (__tcfapi) existuje, ale neodpovedá', '', 'Skúste stránku znova načítať; ak sa opakuje, koliduje druhá cookie lišta.');
			} else {
				var d = 'gdprApplies=' + tc.gdprApplies + ', cmpStatus=' + tc.cmpStatus + ', eventStatus=' + tc.eventStatus + ', tcString=' + (tc.tcString ? tc.tcString.length + ' znakov' : 'prázdny');
				if (tc.gdprApplies === false) {
					add('tcf', 'warn', 'TCF hovorí, že GDPR sa na vás nevzťahuje (gdprApplies=false)', d,
						'Google zobrazuje lištu len návštevníkom z EHP/UK/Švajčiarska. Testujte zo slovenskej IP (nie cez VPN mimo EÚ).');
				} else {
					add('tcf', 'ok', 'Rozhranie TCF funguje', d);
				}
			}
		} else {
			add('tcf', 'info', 'Rozhranie TCF (__tcfapi) na stránke nie je', 'Žiadna certifikovaná lišta (CMP) sa zatiaľ nezaregistrovala.');
		}

		/* 7. Už zadaný súhlas? */
		var ck = document.cookie.split(';').map(function (c) { return c.trim().split('=')[0]; });
		var consentCookies = ck.filter(function (n) { return /^(FCCDCF|FCNEC|euconsent-v2|addtl_consent)$/.test(n); });
		if (consentCookies.length) {
			add('cookie', 'warn', 'Súhlas už bol zadaný (cookies: ' + consentCookies.join(', ') + ')', 'Lišta sa druhýkrát nezobrazí.',
				'Test urobte v novom anonymnom okne alebo vymažte tieto cookies pre relife.sk (F12 → Application → Cookies).');
		} else {
			add('cookie', 'ok', 'Žiadny uložený súhlas Google – lišta by sa mala ukázať');
		}

		/* 8. Konflikt s inou lištou */
		var others = [];
		var gl = { Cookiebot: window.Cookiebot, OneTrust: window.OneTrust, CookieYes: window.cookieyes || window.CookieYes, Complianz: window.cmplz_blocked_scripts || window.complianz, Usercentrics: window.UC_UI, 'Borlabs Cookie': window.BorlabsCookie, 'CookieConsent': window.CookieConsent, Iubenda: window._iub, Didomi: window.Didomi, Termly: window.Termly };
		Object.keys(gl).forEach(function (k) { if (gl[k]) { others.push(k); } });
		if (document.querySelector('[id*="cookie-law-info"], [class*="cmplz"], #cookiebanner, .cc-window')) { others.push('iná cookie lišta v DOM'); }
		if (others.length) {
			add('conflict', 'warn', 'Na stránke je iná cookie lišta: ' + others.join(', '), 'Dve lišty sa rušia; Google nezobrazí svoju správu, ak už existuje iná TCF lišta.',
				'Používajte jednu: buď vypnite druhý plugin, alebo v ňom nastavte Google ako CMP.');
		}
		if (document.getElementById('rl-cookie')) {
			add('rlbanner', 'warn', 'Zobrazuje sa aj vlastná lišta témy RELIFE (#rl-cookie)', 'Okrem Google lišty je zapnutá aj lišta témy pre Google Analytics.',
				'Ak chcete len Google lištu: Vzhľad → Prispôsobiť → RELIFE → vypnite „Zobraziť cookie lištu“ a nechajte meranie riadiť Googlom.');
		}

		/* 9. ads.txt */
		try {
			var t = await fetch('/ads.txt', { cache: 'no-store' });
			var txt = t.ok ? await t.text() : '';
			if (!t.ok) {
				add('adstxt', 'warn', 'ads.txt neexistuje (' + t.status + ')', '', 'Pridajte riadok „google.com, pub-' + pub + ', DIRECT, f08c47fec0942fa0“ (téma ho vytvorí sama, ak je zadané ID v Customizeri) – chýbajúci ads.txt znižuje príjmy a AdSense na to upozorňuje.');
			} else if (txt.indexOf('pub-' + pub) === -1) {
				add('adstxt', 'warn', 'ads.txt neobsahuje pub-' + pub, txt.slice(0, 200), 'Doplňte riadok „google.com, pub-' + pub + ', DIRECT, f08c47fec0942fa0“.');
			} else {
				add('adstxt', 'ok', 'ads.txt obsahuje vaše ID');
			}
		} catch (e) {
			add('adstxt', 'info', 'ads.txt sa nepodarilo načítať', String(e));
		}

		/* 10. Okolnosti testu */
		if (document.getElementById('wpadminbar')) {
			add('admin', 'warn', 'Ste prihlásený vo WordPresse (admin lišta)', '', 'Téma pre prihlásených redaktorov môže skrývať reklamy/tag. Testujte odhlásený alebo v anonymnom okne.');
		}
		var tz = '';
		try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch (e) { /* nič */ }
		if (tz && !/^(Europe|Atlantic\/(Reykjavik|Canary|Madeira|Azores)|Africa\/Ceuta)/.test(tz)) {
			add('region', 'warn', 'Časové pásmo prehliadača (' + tz + ') nie je európske', '', 'GDPR správu vidia len návštevníci z EHP/UK/CH. Testujte zo slovenskej siete bez VPN.');
		}

		return { url: location.href, pub: 'ca-pub-' + pub, when: new Date().toISOString(), results: res, verdict: verdict(res) };
	}

	/* Vyhodnotenie: najpravdepodobnejšia príčina a postup opravy */
	function verdict(res) {
		var order = ['script', 'pub', 'agload', 'fcnet', 'conflict', 'cookie', 'region', 'admin', 'fcreq', 'dom', 'tcf', 'rlbanner'];
		var byId = {};
		res.forEach(function (r) { byId[r.id] = r; });
		for (var i = 0; i < order.length; i++) {
			var r = byId[order[i]];
			if (r && (r.status === 'fail' || (r.status === 'warn' && ['conflict', 'cookie', 'region', 'admin'].indexOf(r.id) > -1))) {
				return { found: true, id: r.id, title: r.title, fix: r.fix };
			}
		}
		var allOk = res.every(function (r) { return r.status === 'ok' || r.status === 'info' || r.id === 'adstxt'; });
		return allOk ? { found: false, title: 'Všetko vyzerá v poriadku – lišta by sa mala zobrazovať.', fix: '' } : { found: false, title: 'Jednoznačná chyba sa nenašla, pozrite upozornenia vyššie.', fix: '' };
	}

	function relifeCmpFormat(r) {
		var icon = { ok: '✅', warn: '⚠️ ', fail: '❌', info: 'ℹ️ ' };
		var out = [];
		out.push('RELIFE – kontrola GDPR lišty AdSense');
		out.push(r.url + '  |  ' + r.pub + '  |  ' + r.when);
		out.push('');
		r.results.forEach(function (x) {
			out.push((icon[x.status] || '•') + ' ' + x.title);
			if (x.detail) { out.push('     ' + x.detail); }
			if (x.fix && x.status !== 'ok') { out.push('     → ' + x.fix); }
		});
		out.push('');
		out.push('VÝSLEDOK: ' + r.verdict.title);
		if (r.verdict.fix) { out.push('NÁVRH OPRAVY: ' + r.verdict.fix); }
		return out.join('\n');
	}

	window.relifeCmpCheck = relifeCmpCheck;
	window.relifeCmpFormat = relifeCmpFormat;

	if (!window.__RELIFE_CMP_NO_AUTORUN) {
		relifeCmpCheck().then(function (r) {
			window.__relifeCmpResult = r;
			console.log(relifeCmpFormat(r));
		});
	}
})();

js.relife.js:
/**
 * RELIFE – interakcie v prehliadači čitateľa.
 * Všetko (hlas v ankete, nálada, uložené články) sa ukladá len lokálne:
 *   localStorage: relife.vote.<id>, relife.mood, relife.saved
 *   Cache API:    relife-saved-v1 (kópia uložených stránok pre offline)
 */
( function () {
	'use strict';

	var data = window.relifeData || {};
	var i18n = data.i18n || {};
	var CACHE = 'relife-saved-v1';

	function lsGet( key, fallback ) {
		try {
			var v = window.localStorage.getItem( key );
			return v === null ? fallback : v;
		} catch ( e ) {
			return fallback;
		}
	}
	function lsSet( key, value ) {
		try {
			window.localStorage.setItem( key, value );
		} catch ( e ) { /* súkromný režim */ }
	}
	/** Odošle udalosť do Google tagu (ak je načítaný). Meno a parametre neobsahujú osobné údaje. */
	function track( name, params ) {
		try {
			if ( typeof window.gtag === 'function' ) { window.gtag( 'event', name, params || {} ); }
		} catch ( e ) { /* sledovanie nesmie ovplyvniť stránku */ }
	}
	function qs( sel, root ) { return ( root || document ).querySelector( sel ); }
	function qsa( sel, root ) { return Array.prototype.slice.call( ( root || document ).querySelectorAll( sel ) ); }

	/* ---------- Uložené články ---------- */
	function getSaved() {
		try {
			var arr = JSON.parse( lsGet( 'relife.saved', '[]' ) );
			return Array.isArray( arr ) ? arr.map( Number ) : [];
		} catch ( e ) {
			return [];
		}
	}
	function setSaved( list ) {
		lsSet( 'relife.saved', JSON.stringify( list ) );
		updateSavedUI();
	}
	function cacheUrl( url, add ) {
		if ( ! window.caches || ! url ) { return; }
		window.caches.open( CACHE ).then( function ( cache ) {
			return add ? cache.add( url ) : cache.delete( url );
		} ).catch( function () {} );
	}
	function updateSavedUI() {
		var saved = getSaved();
		qsa( '.js-saved-count' ).forEach( function ( el ) { el.textContent = String( saved.length ); } );
		qsa( '.js-save' ).forEach( function ( btn ) {
			var on = saved.indexOf( Number( btn.getAttribute( 'data-id' ) ) ) !== -1;
			btn.setAttribute( 'aria-pressed', on ? 'true' : 'false' );
			btn.setAttribute( 'aria-label', on ? ( i18n.unsave || 'Odstrániť z uložených' ) : ( i18n.save || 'Uložiť článok' ) );
		} );
	}
	/* Anonymné počítadlo uložení pre štatistiku v administrácii: len ID článku a smer, bez osobných údajov. */
	function countSave( id, action ) {
		if ( ! data.saveUrl || ! window.fetch ) { return; }
		try {
			fetch( data.saveUrl, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify( { id: id, action: action } ),
				keepalive: true,
				credentials: 'omit'
			} ).catch( function () {} );
		} catch ( e ) { /* nič */ }
	}
	document.addEventListener( 'click', function ( ev ) {
		var btn = ev.target.closest ? ev.target.closest( '.js-save' ) : null;
		if ( ! btn ) { return; }
		ev.preventDefault();
		var id = Number( btn.getAttribute( 'data-id' ) );
		var url = btn.getAttribute( 'data-url' );
		var saved = getSaved();
		var idx = saved.indexOf( id );
		if ( idx === -1 ) {
			saved.push( id );
			cacheUrl( url, true );
			track( 'relife_save_article', { article_id: id } );
			countSave( id, 'save' );
		} else {
			saved.splice( idx, 1 );
			cacheUrl( url, false );
			countSave( id, 'unsave' );
		}
		setSaved( saved );
		if ( qs( '.js-saved-list' ) ) { renderSavedPage(); }
	} );

	function esc( s ) {
		var d = document.createElement( 'div' );
		d.textContent = s == null ? '' : String( s );
		return d.innerHTML;
	}
	function renderSavedPage() {
		var list = qs( '.js-saved-list' );
		var empty = qs( '.js-saved-empty' );
		if ( ! list ) { return; }
		var ids = getSaved();
		if ( ! ids.length ) {
			list.innerHTML = '';
			if ( empty ) { empty.hidden = false; }
			return;
		}
		if ( empty ) { empty.hidden = true; }
		var url = data.restUrl + ( data.restUrl.indexOf( '?' ) === -1 ? '?' : '&' ) + 'include=' + ids.join( ',' ) + '&per_page=50&_fields=id,link,title,relife';
		window.fetch( url ).then( function ( r ) { return r.json(); } ).then( function ( posts ) {
			var byId = {};
			( posts || [] ).forEach( function ( p ) { byId[ p.id ] = p; } );
			list.innerHTML = ids.map( function ( id ) {
				var p = byId[ id ];
				if ( ! p ) { return ''; }
				var r = p.relife || {};
				var title = p.title && p.title.rendered ? p.title.rendered : '';
				var media = r.thumbnail ? '<img src="' + esc( r.thumbnail ) + '" alt="" loading="lazy">' : '<span class="rl-card__initial" aria-hidden="true">' + esc( ( r.section || '' ).charAt( 0 ) ) + '</span>';
				return '<div class="rl-card js-card" data-id="' + id + '"><a class="rl-card__link" href="' + esc( p.link ) + '">' +
					'<span class="rl-card__media" style="background:' + esc( r.color || '#3CFFD0' ) + '">' + media + '<span class="rl-tag rl-tag--dark">' + esc( r.section ) + '</span></span>' +
					'<h3 class="rl-card__title">' + title + '</h3>' +
					'<span class="rl-meta">' + esc( ( r.format ? r.format + ' · ' : '' ) + ( r.readTime || 1 ) + ' min' ) + '</span></a>' +
					'<button type="button" class="rl-save js-save" data-id="' + id + '" data-url="' + esc( p.link ) + '" aria-pressed="true" aria-label="' + esc( i18n.unsave ) + '">' +
					'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4z"/></svg></button></div>';
			} ).join( '' );
			if ( empty && ! list.children.length ) { empty.hidden = false; }
		} ).catch( function () { if ( empty ) { empty.hidden = false; } } );
	}

	/* ---------- Anketa ---------- */
	function initPoll() {
		var poll = qs( '.js-poll' );
		if ( ! poll ) { return; }
		var key = 'relife.vote.' + poll.getAttribute( 'data-poll' );
		var opts = qsa( '.js-opt', poll );
		var note = qs( '.js-poll-note', poll );

		function show( voted, mine ) {
			poll.classList.toggle( 'is-voted', voted );
			opts.forEach( function ( o, i ) {
				var pct = Number( o.getAttribute( 'data-pct' ) ) || 0;
				var on = voted && i === mine;
				o.classList.toggle( 'is-mine', on );
				o.setAttribute( 'aria-pressed', on ? 'true' : 'false' );
				qs( '.js-pct', o ).textContent = voted ? pct + ' %' : '';
				qs( '.js-bar', o ).style.width = voted ? pct + '%' : '0%';
			} );
			if ( note ) { note.textContent = voted ? ( i18n.thanks || '' ) : ( i18n.beforeVote || '' ); }
		}

		var stored = lsGet( key, '' );
		var mine = stored === '' ? -1 : parseInt( stored, 10 );
		show( mine >= 0, mine );

		opts.forEach( function ( o, i ) {
			o.addEventListener( 'click', function () {
				if ( poll.classList.contains( 'is-voted' ) ) { return; }
				lsSet( key, String( i ) );
				show( true, i );
				track( 'relife_poll_vote', { poll_id: poll.getAttribute( 'data-poll' ), option_index: i } );
			} );
		} );
	}

	/* ---------- Karta: anketa / nálada ---------- */
	function initSidecard() {
		var card = qs( '.js-sidecard' );
		if ( ! card ) { return; }
		var tabPoll = qs( '.js-tab-poll', card );
		var tabMood = qs( '.js-tab-mood', card );
		var pPoll = qs( '.js-panel-poll', card );
		var pMood = qs( '.js-panel-mood', card );
		function tab( mood ) {
			pPoll.hidden = mood;
			pMood.hidden = ! mood;
			tabPoll.classList.toggle( 'is-active', ! mood );
			tabMood.classList.toggle( 'is-active', mood );
			tabPoll.setAttribute( 'aria-selected', mood ? 'false' : 'true' );
			tabMood.setAttribute( 'aria-selected', mood ? 'true' : 'false' );
		}
		tabPoll.addEventListener( 'click', function () { tab( false ); } );
		tabMood.addEventListener( 'click', function () { tab( true ); } );
	}

	/* ---------- Nálada: filtrovanie článkov na úvodnej stránke ---------- */
	function initMood() {
		var grid = qs( '.js-today' );
		var moodBtns = qsa( '.js-mood' );
		if ( ! grid || ! moodBtns.length ) { return; }
		var limit = Number( grid.getAttribute( 'data-limit' ) ) || 4;
		var titleEl = qs( '.js-today-title' );
		var status = qs( '.js-mood-status' );
		var statusText = qs( '.js-mood-text' );
		var emptyEl = qs( '.js-today-empty' );
		var moods = data.moods || [];

		function apply( id ) {
			var mood = moods.filter( function ( m ) { return m.id === id; } )[ 0 ] || null;
			var shown = 0;
			qsa( '.js-card', grid ).forEach( function ( card ) {
				var secs = ( card.getAttribute( 'data-sections' ) || '' ).split( ' ' );
				var match = ! mood || mood.sections.some( function ( s ) { return secs.indexOf( s ) !== -1; } );
				var visible = match && shown < limit;
				if ( visible ) { shown++; }
				card.classList.toggle( 'is-hidden', ! visible );
			} );
			moodBtns.forEach( function ( b ) { b.setAttribute( 'aria-pressed', mood && b.getAttribute( 'data-mood' ) === mood.id ? 'true' : 'false' ); } );
			if ( titleEl ) { titleEl.textContent = mood ? ( titleEl.getAttribute( 'data-mood' ) || 'Pre tvoju náladu' ) : titleEl.getAttribute( 'data-default' ); }
			if ( status ) {
				status.hidden = ! mood;
				if ( mood && statusText ) { statusText.innerHTML = ( i18n.moodNow || '' ) + ' <b>' + esc( mood.label ) + '</b> · ' + esc( mood.sections.join( ' · ' ).toUpperCase() ); }
			}
			if ( emptyEl ) {
				emptyEl.hidden = shown > 0;
				emptyEl.textContent = shown > 0 ? '' : ( i18n.moodNone || '' );
			}
		}

		var current = lsGet( 'relife.mood', '' ) || null;
		apply( current );
		moodBtns.forEach( function ( b ) {
			b.addEventListener( 'click', function () {
				var id = b.getAttribute( 'data-mood' );
				current = current === id ? null : id;
				lsSet( 'relife.mood', current || '' );
				apply( current );
				if ( current ) { track( 'relife_mood_select', { mood: current } ); }
			} );
		} );
		var clear = qs( '.js-mood-clear' );
		if ( clear ) {
			clear.addEventListener( 'click', function () {
				current = null;
				lsSet( 'relife.mood', '' );
				apply( null );
			} );
		}
	}

	/* ---------- Filter starších ankiet ---------- */
	function initPollFilters() {
		var wrap = qs( '.js-poll-filters' );
		if ( ! wrap ) { return; }
		wrap.addEventListener( 'click', function ( ev ) {
			var b = ev.target.closest ? ev.target.closest( '.rl-filter' ) : null;
			if ( ! b ) { return; }
			var f = b.getAttribute( 'data-filter' );
			qsa( '.rl-filter', wrap ).forEach( function ( x ) {
				var on = x === b;
				x.classList.toggle( 'is-active', on );
				x.setAttribute( 'aria-pressed', on ? 'true' : 'false' );
			} );
			qsa( '.js-pollcard' ).forEach( function ( c ) {
				c.classList.toggle( 'is-hidden', f !== 'all' && c.getAttribute( 'data-section' ) !== f );
			} );
		} );
	}

	/* ---------- Hľadanie, zdieľanie, progres, spodné menu ---------- */
	function initMisc() {
		var panel = qs( '#rl-search' );
		qsa( '.js-search-toggle' ).forEach( function ( btn ) {
			btn.addEventListener( 'click', function () {
				if ( ! panel ) { return; }
				var mp = qs( '#rl-menu' ), mb = qs( '.js-menu-toggle' );
				if ( mp && ! mp.hidden && mb ) { mb.click(); }
				var open = panel.hidden;
				panel.hidden = ! open;
				qsa( '.js-search-toggle' ).forEach( function ( b ) { b.setAttribute( 'aria-expanded', open ? 'true' : 'false' ); } );
				if ( open ) {
					var input = qs( 'input[type="search"]', panel );
					if ( input ) { input.focus(); window.scrollTo( { top: 0, behavior: 'smooth' } ); }
				}
			} );
		} );

		qsa( '.js-share' ).forEach( function ( btn ) {
			btn.addEventListener( 'click', function () {
				var payload = { title: btn.getAttribute( 'data-title' ), url: btn.getAttribute( 'data-url' ) };
				if ( navigator.share ) {
					navigator.share( payload ).catch( function () {} );
				} else if ( navigator.clipboard ) {
					navigator.clipboard.writeText( payload.url ).then( function () { btn.textContent = 'Odkaz skopírovaný'; } );
				}
			} );
		} );

		var bar = qs( '.js-progress' );
		var art = qs( '.rl-article__main' );
		if ( bar && art ) {
			var onScroll = function () {
				var r = art.getBoundingClientRect();
				var total = r.height - window.innerHeight * 0.5;
				var pct = Math.min( 100, Math.max( 0, ( -r.top + window.innerHeight * 0.3 ) / total * 100 ) );
				bar.style.width = pct + '%';
			};
			window.addEventListener( 'scroll', onScroll, { passive: true } );
			onScroll();
		}

		/* Plávajúca výzva na ďalší článok: len na mobile, v poslednej tretine čítania článku. */
		var next = qs( '.js-next' );
		var body = qs( '.rl-content' );
		if ( next && body && window.matchMedia ) {
			var mq = window.matchMedia( '(max-width: 760px)' );
			var nkey = 'relife.next.' + next.getAttribute( 'data-post' );
			var closed = false;
			try { closed = window.sessionStorage.getItem( nkey ) === '1'; } catch ( e ) { /* nič */ }
			var shown = false;
			var footer = qs( '.rl-footer' );
			var setNext = function ( on ) {
				if ( on === shown ) { return; }
				shown = on;
				if ( on ) {
					next.hidden = false;
					window.requestAnimationFrame( function () { next.classList.add( 'is-on' ); } );
					track( 'relife_next_shown', { article_id: Number( next.getAttribute( 'data-post' ) ) } );
				} else {
					next.classList.remove( 'is-on' );
					window.setTimeout( function () { if ( ! shown ) { next.hidden = true; } }, 260 );
				}
			};
			var checkNext = function () {
				if ( closed || ! mq.matches ) { setNext( false ); return; }
				var r = body.getBoundingClientRect();
				var vh = window.innerHeight;
				var progress = ( vh - r.top ) / r.height; /* kam až v texte siaha spodok obrazovky */
				var footerVisible = footer && footer.getBoundingClientRect().top < vh;
				setNext( progress >= 0.66 && ! footerVisible );
			};
			window.addEventListener( 'scroll', checkNext, { passive: true } );
			window.addEventListener( 'resize', checkNext );
			next.addEventListener( 'click', function ( ev ) {
				if ( ev.target.closest && ev.target.closest( '.js-next-close' ) ) {
					closed = true;
					try { window.sessionStorage.setItem( nkey, '1' ); } catch ( e ) { /* nič */ }
					setNext( false );
				} else if ( ev.target.closest && ev.target.closest( '.rl-next__link' ) ) {
					track( 'relife_next_click', { article_id: Number( next.getAttribute( 'data-post' ) ) } );
				}
			} );
			checkNext();
		}

		var cls = document.body.classList;
		qsa( '.js-tab' ).forEach( function ( a ) {
			var m = a.getAttribute( 'data-match' );
			var active = ( 'home' === m && cls.contains( 'home' ) ) || ( 'saved' === m && cls.contains( 'page-template-template-saved' ) );
			a.classList.toggle( 'is-active', active );
		} );
	}

	/* ---------- Rozbaľovacie menu Sekcie (mobil) ---------- */
	function initMenu() {
		var btn = qs( '.js-menu-toggle' );
		var panel = qs( '#rl-menu' );
		if ( ! btn || ! panel ) { return; }
		function setOpen( open ) {
			panel.hidden = ! open;
			btn.setAttribute( 'aria-expanded', open ? 'true' : 'false' );
			btn.classList.toggle( 'is-active', open );
			btn.setAttribute( 'aria-label', btn.getAttribute( open ? 'data-open-label' : 'data-closed-label' ) || '' );
			document.documentElement.classList.toggle( 'rl-lock', open );
			if ( open ) { panel.scrollTop = 0; }
		}
		btn.addEventListener( 'click', function () { setOpen( panel.hidden ); } );
		panel.addEventListener( 'click', function ( ev ) {
			if ( ev.target.closest && ev.target.closest( 'a' ) ) { setOpen( false ); }
		} );
		document.addEventListener( 'keydown', function ( ev ) {
			if ( ev.key === 'Escape' && ! panel.hidden ) { setOpen( false ); btn.focus(); }
		} );
		window.addEventListener( 'resize', function () {
			if ( window.innerWidth > 760 && ! panel.hidden ) { setOpen( false ); }
		} );
	}

	function init() {
		updateSavedUI();
		initPoll();
		initSidecard();
		initMood();
		initPollFilters();
		initMisc();
		initMenu();
		renderSavedPage();
		document.documentElement.classList.add( 'rl-ready' );
	}
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', init );
	} else {
		init();
	}
}() );

